Translate("frFR", "the-deadmines", {
	title = "Les Mortemines",
	aliases = { "Mortemines" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Mortemines s'étendent sous le village de {link:moonbrook}Ruisselune{/link}, en {link:westfall}Marche de l'Ouest{/link}. Elles furent jadis les plus riches mines d'or des terres des hommes. Elles sont aujourd'hui le cœur secret de la {link:defias-brotherhood}Confrérie défias{/link}. Dans leurs profondeurs, les tailleurs de pierre d'{link:edwin-vancleef}Edwin VanCleef{/link} et les gobelins qu'ils ont engagés construisent une chose que nul à {link:stormwind-city}Stormwind{/link} n'a encore vue : un grand navire de guerre, caché dans une grotte marine au fond des mines.]=],
		},
		{
			title = "Origines",
			text = [=[Pendant des générations, les mines sous {link:moonbrook}Ruisselune{/link} envoyèrent leur or au trésor du {link:kingdom-of-stormwind}royaume de Stormwind{/link}. Quand la {link:horde}Horde{/link} rasa {link:stormwind-city}Stormwind{/link} lors de la {link:first-war}Première Guerre{/link}, les mineurs s'enfuirent et les chantiers se turent. Les galeries furent abandonnées aux ténèbres, et les gens se mirent à les appeler les Mortemines. Elles restèrent vides pendant les années d'exil et de reconstruction. Quand les maçons trahis vinrent vers l'ouest, ils y trouvèrent une forteresse déjà creusée pour eux.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[La Confrérie a fait de la vieille mine son sanctuaire. Des mineurs défias creusent ses puits, et des sorciers et des évocateurs de la Confrérie gardent ses salles. Des artisans et des ingénieurs gobelins à la solde de la Confrérie taillent le bois, fondent le métal et assemblent des machines. Un {link:ogres}ogre{/link} garde la première porte. Tout en bas, là où les galeries s'ouvrent sur la mer, le navire est presque prêt, et son capitaine et son équipage attendent l'ordre de leur maître. Ce que {link:edwin-vancleef}VanCleef{/link} compte en faire, seule la Confrérie le sait. Beaucoup craignent qu'il ne soit destiné à {link:stormwind-city}Stormwind{/link}.]=],
		},
		{
			title = "Dans les mines",
			text = [=[• {b}L'aile effondrée.{/b} Avant l'entrée de la Confrérie, un passage latéral mène à des galeries où un groupe de mineurs et d'explorateurs nains fut enseveli quand le plafond s'écroula. Ils ne reposent pas en paix. Leurs morts arpentent encore les ténèbres avec pioches et dynamite.
• {b}La salle du mât.{/b} Ici, les gobelins du maître bûcheron {link:sneed}Sneed{/link} taillent de grandes poutres pour le navire.
• {b}La fonderie.{/b} Ici, le gobelin {link:gilnid}Gilnid{/link} fond le métal des mines.
• {b}La {link:ironclad-cove}Crique du cuirassé{/link}.{/b} Au fond des mines s'ouvre une grotte sur la mer, où le navire de la Confrérie est à l'ancre. Sa porte est scellée, et seuls la poudre et le canon l'ouvriront.
• {b}L'issue cachée.{/b} Depuis la crique, un passage monte vers les collines derrière {link:moonbrook}Ruisselune{/link}, près de la mer.]=],
		},
		{
			title = "Ceux qui vivent en bas",
			text = [=[Les serviteurs de la Confrérie sont nombreux ici. Le contremaître {link:rhahkzor}Rhahk'Zor{/link}, les gobelins {link:sneed}Sneed{/link} et {link:gilnid}Gilnid{/link}, et l'équipage du navire sous le capitaine {link:captain-greenskin}Greenskin{/link} obéissent tous à {link:edwin-vancleef}Edwin VanCleef{/link}. Des dangers plus rares rôdent aussi dans les galeries, parmi eux un mineur d'une grande force connu sous le nom de Mineur Johnson.]=],
		},
	},
})

Translate("frFR", "ironclad-cove", {
	title = "Crique du cuirassé",
	sections = {
		{
			title = "Résumé",
			text = [=[La Crique du cuirassé est une vaste grotte marine au fond des {link:the-deadmines}Mortemines{/link}, là où les galeries des anciennes mines d'or débouchent sur la Grande mer. C'est ici que la {link:defias-brotherhood}Confrérie défias{/link} garde son plus grand secret. Un navire de guerre est à l'ancre sur l'eau sombre, bâti avec le bois taillé dans la salle du mât et le métal fondu dans la fonderie. Des pirates de la Confrérie forment son équipage. Depuis son pont supérieur, {link:edwin-vancleef}Edwin VanCleef{/link} commande toute sa Confrérie, et c'est ici qu'il a choisi de tenir tête.]=],
		},
	},
})

Translate("frFR", "edwin-vancleef", {
	title = "Edwin VanCleef",
	subtitle = "Chef de la Confrérie défias",
	found = "Le pont supérieur du navire, dans la Crique du cuirassé",
	hint = [=[Apprenez son nom auprès de la milice de Marche de l'Ouest, ou cherchez-le au fond des Mortemines.]=],
	allegiance = [=[Confrérie défias · autrefois la guilde des Tailleurs de pierre]=],
	aliases = { "VanCleef", "Edwin" },
	sections = {
		{
			title = "Résumé",
			text = [=[Edwin VanCleef était le maître de la {link:stonemasons-guild}guilde des Tailleurs de pierre{/link} de {link:stormwind-city}Stormwind{/link}. C'est sa guilde qui releva la capitale des cendres de la {link:first-war}Première Guerre{/link}. Une fois l'ouvrage achevé, la {link:house-of-nobles}Chambre des nobles{/link} refusa de payer aux maçons ce qu'elle leur devait. VanCleef les mena à la révolte et quitta la ville en jurant vengeance. Il est aujourd'hui le chef de la {link:defias-brotherhood}Confrérie défias{/link}, maître de la {link:westfall}Marche de l'Ouest{/link}, et depuis une crique cachée sous la terre, il prépare son coup contre le royaume qui l'a trahi.]=],
		},
		{
			title = "Importance",
			text = [=[VanCleef est la blessure que {link:stormwind-city}Stormwind{/link} s'est infligée à lui-même. C'était un bâtisseur, pas un bandit, et ceux qui l'ont connu se souviennent d'un homme talentueux et travailleur. Sa Confrérie est née d'une injustice réelle. Pourtant, sa vengeance a frappé le plus durement le petit peuple de {link:westfall}Marche de l'Ouest{/link}, et non les nobles qui l'ont floué, et elle a mené à la ruine le grenier même du royaume.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il dirigea la guilde des Tailleurs de pierre lors de la reconstruction de {link:stormwind-city}Stormwind{/link} après les guerres.
• Quand on offrit à quelques maçons de haut rang des postes au gouvernement, il refusa le sien par loyauté envers toute la guilde.
• Il mena l'émeute des maçons et s'enfuit de la ville à son issue. La reine {link:tiffin-wrynn}Tiffin Wrynn{/link} fut tuée dans le chaos.
• Il rassembla les maçons exilés en {link:westfall}Marche de l'Ouest{/link} et fonda la {link:defias-brotherhood}Confrérie défias{/link}.
• Il fit des {link:the-deadmines}Mortemines{/link} sa place forte et engagea des gobelins pour construire un navire de guerre dans leurs profondeurs.
• Son lieutenant, {link:bazil-thredd}Bazil Thredd{/link}, fut capturé et emprisonné à {link:the-stockade}la Prison{/link} de Stormwind.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique ne rapporte la naissance de VanCleef, sa famille ni les années qui précédèrent sa maîtrise de la guilde. Cette entrée ne consigne que ses actes et les paroles de ceux qui l'ont connu.]=],
		},
	},
	chapters = {
		{
			title = "Un nom surgi du passé",
			hint = "Portez la question des tailleurs de pierre au SI:7.",
			text = [=[Longtemps, la Confrérie n'eut pas de visage. Puis {link:master-mathias-shaw}Mathias Shaw{/link}, du {link:si-7}SI:7{/link}, lui en donna un. L'ancienne guilde des tailleurs de pierre, écrivit-il, était dirigée par un homme nommé Edwin VanCleef, un homme qui avait rebâti {link:stormwind-city}Stormwind{/link} et qu'on n'en avait pas remercié.]=],
		},
		{
			title = "La lettre du messager",
			hint = [=[Interceptez le messager de la Confrérie sur les routes de Marche de l'Ouest.]=],
			text = [=[Un messager défias parcourait les routes entre {link:moonbrook}Ruisselune{/link}, la carrière et la mine de {link:jangolode-mine}Jangolode{/link}. Le message qu'il portait était la preuve formelle que la Confrérie obéissait à VanCleef. Il ne disait pas où celui-ci se cachait.]=],
		},
		{
			title = "Le repaire",
			hint = "Suivez le traître défias jusqu'au repaire de la Confrérie.",
			text = [=[Un voleur capturé racheta sa vie en conduisant la milice à {link:moonbrook}Ruisselune{/link}. Sous le village, dans la vieille mine d'or, VanCleef et ses maçons attendaient.]=],
		},
		{
			title = "La chute du chef",
			hint = "Descendez au fond des Mortemines.",
			text = [=[Au fond des mines, sur le pont de son navire, VanCleef affronta ceux qui étaient venus pour lui. Il ne se rendit pas. Il appela ses gardes à ses côtés et combattit, comme {link:baros-alexston}Baros Alexston{/link} se souvenait de l'avoir vu combattre dans sa jeunesse, sans égal. Quand il tomba, sa tête fut rapportée à la {link:sentinel-hill}Colline des sentinelles{/link}.]=],
		},
		{
			title = "La lettre jamais envoyée",
			hint = "Fouillez VanCleef, et remettez ce que vous trouverez.",
			text = [=[Parmi les affaires de VanCleef se trouvait une lettre scellée, jamais envoyée, adressée à {link:baros-alexston}Baros Alexston{/link}, l'architecte de la cité de {link:stormwind-city}Stormwind{/link}. Baros l'avait connu à la guilde. En la lisant, il qualifia VanCleef d'idéaliste et de romantique encore, un homme dévoré par la vengeance. Il avoua aussi qu'il ne pouvait pas entièrement le blâmer.]=],
		},
	},
	mentions = {
		{
			text = [=[La {link:defias-brotherhood}Confrérie défias{/link}, le billet du voleur]=],
		},
		{
			text = [=[La {link:defias-brotherhood}Confrérie défias{/link}, portée à {link:master-mathias-shaw}Mathias Shaw{/link}]=],
		},
		{
			text = [=[{link:bazil-thredd}Bazil Thredd{/link}, de la part de {link:baros-alexston}Baros Alexston{/link}]=],
		},
		{ text = "Red Silk Bandanas" },
	},
	bonds = {
		{ id = "gryan-stoutmantle", name = "Gryan Stoutmantle", note = "le traque" },
		{ id = "baros-alexston", name = "Baros Alexston", note = "jadis maçon de sa guilde" },
		{ id = "bazil-thredd", name = "Bazil Thredd", note = "son lieutenant" },
		{ id = "master-mathias-shaw", name = "Maître Mathias Shaw", note = "l'a nommé" },
		{ id = "tiffin-wrynn", name = "Tiffin Wrynn", note = "morte dans l'émeute qu'il mena" },
		{ id = "captain-greenskin", name = "Capitaine Greenskin", note = "capitaine de son navire" },
		{ id = "the-defias-traitor", name = "Le traître défias", note = "l'a trahi" },
	},
})

Translate("frFR", "rhahkzor", {
	title = "Rhahk'Zor",
	subtitle = "Le contremaître",
	found = "La première porte des Mortemines",
	hint = "Affrontez l'ogre qui garde la première porte des mines.",
	allegiance = "Confrérie défias",
	sections = {
		{
			title = "Résumé",
			text = [=[Rhahk'Zor est un {link:ogres}ogre{/link} à la solde de la {link:defias-brotherhood}Confrérie défias{/link}, et le contremaître de ses mines. Il garde la première porte des {link:the-deadmines}Mortemines{/link}. Sa tâche est d'arrêter tout intrus qui passe par les galeries, et il se vante que {link:edwin-vancleef}VanCleef{/link} paie bien chaque tête.]=],
		},
		{
			title = "Importance",
			text = [=[Rhahk'Zor montre jusqu'où la Confrérie est allée chercher des alliés. Des maçons qui bâtissaient jadis pour un roi gardent aujourd'hui un {link:ogres}ogre{/link} à leur porte.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il presse les mineurs défias à la tâche.
• Il garde la porte entre la mine supérieure et les salles de la Confrérie.]=],
		},
	},
	bonds = {
		{ id = "edwin-vancleef", name = "Edwin VanCleef", note = "le paie" },
	},
})

Translate("frFR", "sneed", {
	title = "Sneed",
	subtitle = "Maître bûcheron",
	found = "La salle du mât des Mortemines",
	hint = [=[Affrontez le maître bûcheron gobelin qui pilote un déchiqueteur dans les profondeurs.]=],
	allegiance = "Confrérie défias · mercenaires gobelins",
	aliases = { "Déchiqueteur de Sneed" },
	sections = {
		{
			title = "Résumé",
			text = [=[Sneed est un maître bûcheron gobelin au service de la Confrérie. Du siège d'un grand déchiqueteur, une machine marchante faite de lames et d'engrenages, il surveille les sculpteurs sur bois qui taillent les poutres du navire de {link:edwin-vancleef}VanCleef{/link}. Quand le déchiqueteur est brisé, Sneed en sort lui-même pour combattre.]=],
		},
		{
			title = "Importance",
			text = [=[Le déchiqueteur de Sneed est une merveille, même parmi les machines gobelines. Les {link:gnomes}gnomes{/link} de {link:gnomeregan}Gnomeregan{/link} convoitent sa source d'énergie : grâce à elle, pensent-ils, leurs grandes foreuses pourraient percer la roche jusqu'à leur cité perdue.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il surveille la taille des poutres du navire.
• Il pilote le seul déchiqueteur en état de marche des {link:the-deadmines}Mortemines{/link}.]=],
		},
	},
	mentions = {
		{ text = "Underground Assault" },
	},
	bonds = {
		{ id = "gilnid", name = "Gilnid", note = "un autre gobelin des chantiers" },
		{ id = "edwin-vancleef", name = "Edwin VanCleef", note = "son employeur" },
	},
})

Translate("frFR", "gilnid", {
	title = "Gilnid",
	subtitle = "Le fondeur",
	found = "La fonderie des Mortemines",
	hint = "Affrontez le fondeur gobelin dans la fonderie des mines.",
	allegiance = "Confrérie défias · mercenaires gobelins",
	sections = {
		{
			title = "Résumé",
			text = [=[Gilnid est le fondeur gobelin des {link:the-deadmines}Mortemines{/link}. Dans sa fonderie, le minerai des mines est fondu et coulé en métal pour les besoins de la Confrérie. Ses artisans et ses ingénieurs s'affairent autour de lui dans la chaleur et les fumées.]=],
		},
		{
			title = "Importance",
			text = [=[La fonderie de Gilnid est la forge de la guerre de {link:edwin-vancleef}VanCleef{/link}. Ceux qui cherchent la source du poison dans les puits de {link:westfall}Marche de l'Ouest{/link} ont tourné leurs regards vers les grands chantiers cachés dans ces mines.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il fond le métal des {link:the-deadmines}Mortemines{/link} pour la Confrérie.]=],
		},
	},
	bonds = {
		{ id = "sneed", name = "Sneed", note = "un autre gobelin des chantiers" },
		{ id = "edwin-vancleef", name = "Edwin VanCleef", note = "son employeur" },
	},
})

Translate("frFR", "captain-greenskin", {
