	},
})

Translate("frFR", "mr-smite", {
	title = "Mr. Smite",
	subtitle = "Le second du navire",
	found = "Les quais de la Crique du cuirassé",
	hint = "Affrontez le second qui garde le chemin du navire.",
	allegiance = "Confrérie défias",
	aliases = { "Smite" },
	sections = {
		{
			title = "Résumé",
			text = [=[Mr. Smite est le second du navire de la Confrérie, un {link:tauren}tauren{/link} d'une grande force qui garde les quais de la {link:ironclad-cove}Crique du cuirassé{/link}. Quand des intrus pénètrent dans la crique, c'est lui qui donne l'alarme et appelle l'équipage à les repousser. Il change d'armes au fil du combat.]=],
		},
		{
			title = "Importance",
			text = [=[Un {link:tauren}tauren{/link} parmi les {link:defias-brotherhood}Défias{/link} est un spectacle étrange. Quoi qu'il l'ait mené si loin des plaines de son peuple, il sert désormais le navire de {link:edwin-vancleef}VanCleef{/link} de toute sa force.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il commande l'équipage au nom du capitaine {link:captain-greenskin}Greenskin{/link}.
• Il garde les quais où le navire est à l'ancre.]=],
		},
	},
	bonds = {
		{ id = "captain-greenskin", name = "Capitaine Greenskin", note = "son capitaine" },
		{ id = "edwin-vancleef", name = "Edwin VanCleef", note = "son maître" },
	},
})

Translate("frFR", "cookie", {
	title = "Cookie",
