		{
			title = "Résumé",
			text = [=[Cookie est le cuisinier du navire de la Confrérie, et c'est un {link:murlocs}murloc{/link}. Nul ne saurait dire comment un murloc en est venu à servir aux fourneaux des {link:defias-brotherhood}Défias{/link}. Quand le navire est attaqué, il se bat avec les outils de son métier.]=],
		},
		{
			title = "Importance",
			text = [=[Cookie prouve que la Confrérie accepte toute main qui la sert, même une main palmée.]=],
