	},
	bonds = {
		{ id = "captain-greenskin", name = "Capitaine Greenskin", note = "son capitaine" },
	},
})

Translate("frFR", "foreman-thistlenettle", {
	title = "Contremaître Thistlenettle",
	subtitle = "Contremaître disparu de la Ligue des explorateurs",
	found = "L'aile effondrée, hors de la porte de la Confrérie",
	hint = [=[Affrontez le nain mort-vivant dans les galeries effondrées des Mortemines.]=],
	allegiance = "Ligue des explorateurs (autrefois)",
	aliases = { "Thistlenettle" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le contremaître Thistlenettle était un {link:dwarves}nain{/link} de la {link:explorers-league}Ligue des explorateurs{/link} qui mena une équipe au plus profond de la vaste mine sous {link:moonbrook}Ruisselune{/link}. Des voleurs apparurent dans les galeries, puis la galerie s'effondra. Son frère Wilder en réchappa. On n'entendit plus jamais parler du contremaître ni de son équipe. Il arpente aujourd'hui les galeries obscures parmi les morts, avec les mineurs ensevelis à ses côtés.]=],
		},
		{
			title = "Importance",
			text = [=[Thistlenettle est une victime des {link:the-deadmines}Mortemines{/link} avant même qu'on atteigne la porte de la Confrérie. Son frère attend à {link:stormwind-city}Stormwind{/link} la moindre nouvelle de lui.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il dirigeait l'équipe naine dans la mine sous {link:moonbrook}Ruisselune{/link}.
• Il portait toujours son insigne de la {link:explorers-league}Ligue des explorateurs{/link}.]=],
		},
	},
	mentions = {
		{ text = "Oh Brother..." },
		{ text = "Collecting Memories" },
	},
	bonds = {
		{ id = "wilder-thistlenettle", name = "Wilder Thistlenettle", note = "son frère" },
	},
})
